import java.util.*;
import java.io.*;

public class Main {
    static long[] shortestPaths(int n, long[][] edges) {
        // Write your solution here
        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        long[][] edges = new long[m][3];
        for (int i = 0; i < m; i++) {
            for (int k = 0; k < 3; k++) {
                in.nextToken();
                edges[i][k] = (long) in.nval;
            }
        }
        long[] dist = shortestPaths(n, edges);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < dist.length; i++) sb.append(dist[i]).append(i + 1 < dist.length ? " " : "\n");
        System.out.print(sb);
    }
}
